import { X509Certificate } from "crypto";
import * as fs from "fs";
import * as path from "path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { decodeBase64String, GOOGLE_PUBLIC_KEY } from "@/app/config";

import { verifyAttestation } from "../attestation";
import { GRAPHENEOS_ALLOWLIST_SNAPSHOT } from "../grapheneos-allowlist";

/**
 * Real key attestation chain generated by the GrapheneOS Auditor app on a Pixel 9 running
 * GrapheneOS 2025110600, with an app attest key, followed by the Google root which signs it.
 * https://github.com/GrapheneOS/Auditor/tree/main/samples/5
 */
const FIXTURES = path.join(__dirname, "fixtures", "grapheneos-pixel9-auditor");
const x509Chain = [
  "0_cert_0.der",
  "0_cert_1.der",
  "0_cert_2.der",
  "0_cert_3.der",
  "0_cert_4.der",
  "1_google_root_3.der",
].map(
  (file) => new X509Certificate(fs.readFileSync(path.join(FIXTURES, file))),
);

const challenge = Buffer.from(
  "7387551f024289bff8c37c8f3f5fe676b2949fcec23d391dc00ef40a02f64ea2",
  "hex",
).toString("utf-8");

const verify = (overrides: Partial<Parameters<typeof verifyAttestation>[0]>) =>
  verifyAttestation({
    attestationCrl: { entries: {} },
    attestKey: { requiredForSelfSigned: true },
    bundleIdentifiers: ["app.attestation.auditor"],
    challenge,
    googlePublicKeys: GOOGLE_PUBLIC_KEY.split(",").map(decodeBase64String),
    signatureDigests: [
      "990e04f0864b19f14f84e0e432f7a393f297ab105a22c1e1b10b442a4a62c42c",
    ],
    trustedSelfSignedBootKeys: new Set(
      GRAPHENEOS_ALLOWLIST_SNAPSHOT.verifiedBootKeys,
    ),
    x509Chain,
    ...overrides,
  });

describe("Real GrapheneOS key attestation (Auditor app on a Pixel 9)", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2025-11-10T00:00:00.000Z"));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("should accept the chain and pin the attest key", async () => {
    const result = await verify({});
    expect(result).toMatchObject({
      deviceDetails: {
        attestKey: expect.objectContaining({ kty: "EC" }),
        deviceLocked: true,
        platform: "android",
        verifiedBootKey:
          "9e6a8f3e0d761a780179f93acd5721ba1ab7c8c537c7761073c0a754b0e932de",
        verifiedBootState: 1,
      },
      success: true,
    });
  });

  it("should accept the chain pinned to its own attest key", async () => {
    const registration = await verify({});
    const pinned = registration.success
      ? registration.deviceDetails.platform === "android"
        ? registration.deviceDetails.attestKey
        : undefined
      : undefined;
    const result = await verify({ attestKey: { pinned } });
    expect(pinned).toBeDefined();
    expect(result.success).toBe(true);
  });

  it.each([
    [
      "a verified boot key not in the allowlist",
      { trustedSelfSignedBootKeys: new Set<string>() },
      "VerifiedBootKey of the self-signed OS is not allowed",
    ],
    [
      "another app signing certificate",
      { signatureDigests: ["00".repeat(32)] },
      "The app signing certificate does not match",
    ],
    [
      "another challenge",
      { challenge: "other" },
      "The received challenge does not match",
    ],
  ])("should reject %s", async (_, overrides, reason) => {
    const result = await verify(overrides);
    expect(result).toMatchObject({
      reason: expect.stringContaining(reason),
      success: false,
    });
  });

  it("should reject the chain pinned to another attest key", async () => {
    const registration = await verify({});
    const result = await verify({
      attestKey: {
        pinned: registration.success ? registration.hardwareKey : undefined,
      } as Parameters<typeof verifyAttestation>[0]["attestKey"],
    });
    expect(result).toMatchObject({
      reason: expect.stringContaining("registered attest key"),
      success: false,
    });
  });
});
